"""
将 [1, 1, 128, 128] 的 tensor 按 16(行) × 32(列) 分形重排。

排布规则：
  - 原始矩阵按行优先展开（128 行 × 128 列）
  - 按 16 行 × 32 列切块，共 (128/16) × (128/32) = 8 × 4 = 32 个分形
  - 分形之间按行优先排布（先遍历列方向，再换下一行分形）
  - 分形内部也按行优先（16 行 × 32 列）

索引映射公式（原始位置 [r, c]）：
  block_row = r // 16
  block_col = c // 32
  inner_r   = r %  16
  inner_c   = c %  32
  分形编号   = block_col * 8 + block_row        # 分形间 N 排布（列优先）
  新索引     = 分形编号 * (16 * 32) + inner_r * 32 + inner_c

验证：
  原始 [1, 0]（第 129 个，索引 128）
    block_row=0, block_col=0, inner_r=1, inner_c=0
    分形编号 = 0, 新索引 = 0 * 512 + 1 * 32 + 0 = 32  →  第 33 个 ✓
  原始 [16, 0]（第 17 行第 1 个，索引 2048）
    block_row=1, block_col=0, inner_r=0, inner_c=0
    分形编号 = 0*8 + 1 = 1, 新索引 = 1 * 512 + 0 = 512  →  第 17 行第 1 个 ✓
"""

import os
import torch

TOTAL_ROW = 128
TOTAL_COL = 128
TILE_ROW = 16
TILE_COL = 32


def rearrange_16x32(tensor_4d):
    """对 [1, 1, 128, 128] 的 tensor 做按 16x32 分形的重排。

    输入: shape = [1, 1, 128, 128]，行优先展开
    输出: shape = [1, 1, 128, 128]，按 16x32 分形排布后展平再 reshape 回去
          （形状不变，只是元素顺序变了）
    """
    assert tensor_4d.dim() == 4, f"期望 4 维 tensor，实际 {tensor_4d.dim()} 维"
    b, n, r, c = tensor_4d.shape
    assert (r, c) == (TOTAL_ROW, TOTAL_COL), f"期望后两维为 [128,128]，实际 [{r},{c}]"

    # 展平成 [128, 128] 方便处理
    mat = tensor_4d[0, 0]  # [128, 128]

    # 1) reshape 成分形网格: [8, 16, 4, 32]
    #    第一维 8 = 行方向分形数(128/16)
    #    第二维 16 = 分形内行数
    #    第三维 4 = 列方向分形数(128/32)
    #    第四维 32 = 分形内列数
    block_row_num = r // TILE_ROW  # 8
    block_col_num = c // TILE_COL  # 4
    reshaped = mat.reshape(block_row_num, TILE_ROW, block_col_num, TILE_COL)

    # 2) 分形编号按 N 排布（列优先）移到前面：[4, 8, 16, 32]
    #    [block_col, block_row, inner_r, inner_c]
    #    前两维 [4,8] 是 32 个分形的列优先编号（先走 block_row 方向，再换 block_col）
    #    后两维 [16,32] 是分形内部的行优先排布（Z 排布）
    permuted = reshaped.permute(2, 0, 1, 3)  # [4, 8, 16, 32]

    # 3) 展平：先按分形编号(8*4=32 个)顺序，每个分形内 16*32=512 个元素
    #    最终得到 32*512 = 16384 个元素的一维序列
    flattened = permuted.reshape(-1)  # [16384]

    # 4) reshape 回 [1, 1, 128, 128]（形状不变，元素顺序已重排）
    return flattened.reshape(1, 1, TOTAL_ROW, TOTAL_COL)


def orig_to_new_index(r, c):
    """原始位置 [r, c] 在重排后的一维索引（正向映射，不依赖数据值）。"""
    block_row = r // TILE_ROW
    block_col = c // TILE_COL
    inner_r = r % TILE_ROW
    inner_c = c % TILE_COL
    block_row_num = TOTAL_ROW // TILE_ROW  # 8
    block_idx = block_col * block_row_num + block_row  # 分形间 N 排布（列优先）
    return block_idx * (TILE_ROW * TILE_COL) + inner_r * TILE_COL + inner_c


def print_matrix_128x128(tensor_4d, name="matrix", max_rows=4):
    """打印 [1,1,128,128] tensor 的前 max_rows 行，每行 128 个元素。"""
    mat = tensor_4d[0, 0]  # [128, 128]
    print(f"\n=== {name} (shape={list(tensor_4d.shape)}, 前 {max_rows} 行) ===")
    for i in range(min(max_rows, mat.shape[0])):
        row = mat[i].tolist()
        # 打印前 8 个和后 8 个，中间用 ... 省略，避免刷屏
        head = row[:8]
        tail = row[-8:]
        print(f"  row[{i:3d}]: {head} ... {tail}")
    print(f"  ... (共 {mat.shape[0]} 行 × {mat.shape[1]} 列)")


